/** Messages with values: each captured group becomes the value named at the same position in `names`. */
export const ERROR_PATTERNS: { pattern: RegExp; key: string; names: string[] }[] = [
  { pattern: /^Free (\d+) seats before this downgrade$/, key: "err_freeSeats", names: ["count"] },
  { pattern: /^Attach a receipt for expenses above (.+)$/, key: "err_receiptAbove", names: ["amount"] },
  { pattern: /^The period up to (.+) is locked$/, key: "err_periodLocked", names: ["date"] },
  { pattern: /^Enter the exchange rate from (\S+) to (\S+)$/, key: "err_exchangeRate", names: ["from", "to"] },
  { pattern: /^Only ([\d.,]+) is left to pay$/, key: "err_leftToPay", names: ["amount"] },
  { pattern: /^"(.+)" needs at least two choices$/, key: "err_fieldTwoChoices", names: ["name"] },
  { pattern: /^Two fields are named "(.+)"$/, key: "err_fieldDuplicate", names: ["name"] },
  { pattern: /^This plan allows (\d+) users and (\d+) have access; remove access first$/, key: "err_seatsUsed", names: ["seats", "used"] },
  { pattern: /^Only ([\d.]+) day\(s\) left in (\d+); this request needs ([\d.]+)$/, key: "err_leaveBalance", names: ["left", "year", "need"] },
  { pattern: /^The company still owes (\d+) invoice\(s\): settle or credit them first$/, key: "err_stillOwes", names: ["count"] },
]
